vms.command:
exec kitty --class otter-tools -e bash -c 'vm="$(virsh list --all --name 2>/dev/null | grep -v '"'"'^$'"'"' | fzf --cycle --gutter '"'"' '"'"' --pointer '"'"'▌'"'"' --color '"'"'bg:#080D10,bg+:#183039,fg:#C5D6D8,hl:#4DDDD5,pointer:#4DDDD5'"'"' --prompt '"'"'  VM > '"'"' --preview '"'"'virsh dominfo {+} 2>/dev/null'"'"' --preview-window=right:40%)"
[ -z "$vm" ] && exit 0
state="$(virsh domstate "$vm" 2>/dev/null)"
action="$(printf '"'"'  start
  shutdown
  reboot
  force-off
  snapshot'"'"' | fzf --prompt "  $vm [$state] > " --color '"'"'bg:#080D10,bg+:#183039,fg:#C5D6D8,hl:#4DDDD5,pointer:#4DDDD5'"'"')"
case "$action" in
  *start)     virsh start "$vm" && notify-send "VM" "Starting $vm" ;;
  *shutdown)  virsh shutdown "$vm" ;;
  *reboot)    virsh reboot "$vm" ;;
  *force-off) virsh destroy "$vm" ;;
  *snapshot)  virsh snapshot-create-as "$vm" "snap-$(date +%Y%m%d-%H%M)" && notify-send "VM" "Snapshot created" ;;
esac
'
